Here is a clean Template Method implementation in Python. The skeleton `sort()` lives in the base class and the concrete algorithms implement the variant `do_sort()` step while re-using the common `compare` / `swap` primitives.

```python
from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def __init__(self, data):
        self.data = list(data)

    # Template Method
    def sort(self):
        self._before_sort()
        self.do_sort()          # primitive operation - algorithm specific
        self._after_sort()
        return self.data

    def _before_sort(self):
        # hook
        pass

    def _after_sort(self):
        # hook
        pass

    # Primitive operations used by all algorithms
    def compare(self, a, b):
        return (a > b) - (a < b)

    def swap(self, i, j):
        self.data[i], self.data[j] = self.data[j], self.data[i]

    @abstractmethod
    def do_sort(self):
        pass


class BubbleSort(SortAlgorithm):
    def do_sort(self):
        n = len(self.data)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(self.data[j], self.data[j + 1]) > 0:
                    self.swap(j, j + 1)


class SelectionSort(SortAlgorithm):
    def do_sort(self):
        n = len(self.data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(self.data[j], self.data[min_idx]) < 0:
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)


# Test
if __name__ == "__main__":
    ints = [5, 2, 9, 1, 5, 6]
    strs = ["banana", "apple", "cherry"]

    for Algo in [BubbleSort, SelectionSort]:
        a = Algo(ints.copy())
        print(Algo.__name__, "ints :", a.sort())

        b = Algo(strs.copy())
        print(Algo.__name__, "strs :", b.sort())
```

`SortAlgorithm.sort()` is the template that defines the invariant skeleton. `BubbleSort` and `SelectionSort` provide their own `do_sort()` implementations, but both reuse the same `compare` and `swap` primitives supplied by the base class.
